using System.Collections.Generic;using Compose.Net;using SharpExtensions;using UnityEngine.UIElements;// ReSharper disable ArrangeNamespaceBodynamespace Compose.Net.Unity.Samples.Behaviors.Content{    internal partial class ButtonSample : ComposeUI    {#pragma warning disable CS0414        [SerializeField] private Texture2D texture = null!;        [SerializeField] private Material material = null!;#pragma warning restore CS0414        [Composable]        protected override void Content()        {            Layout();        }        [Composable]        protected override void Preview()        {            Layout();        }        [Composable]        private void Layout()        {            Column(                verticalArrangement: Arrangement.Center,                horizontalAlignment: Alignment.CenterHorizontally,                modifier: Modifier                    .FillMaxSize(),                content: Button            );        }        [Composable]        private static void Button()        {            var interactionSource = Remember(MutableInteractionSource);            var hovered = interactionSource.CollectIsHoveredAsState().Value;            var shadowProgress = AnimateFloatAsState(hovered.ToInt()).Value;            var pressed = interactionSource.CollectIsPressedAsState().Value;            Box(                contentAlignment: Alignment.Center,                modifier: Modifier                    .Height(200.Dp())                    .Width(600.Dp())                    .Background(Color.LightGreen)                    .Padding(16.Dp())                    .Clip(RoundedCornerShape(AnimateFloatAsState(hovered ? 48 : 16).Value.Dp()))                    .BackdropBlur(1.Dp())                    .DropShadow(                        shape: RoundedCornerShape(16.Dp()),                        shadow: Shadow(                            spread: 20.Dp(),                            color: Color.LerpUnclamped(new Color(), Color.Black, shadowProgress)                            ,                            radius: 32.Dp() * shadowProgress                        )                    )                    .Clickable(                        onClick: () => Debug.Log("Click")                    ),                content: () =>                {                    Text(                        text: pressed ? "Clicked" : "Click me",                        color: Color.White,                        fontSize: 80.Sp()                    );                }            );        }    }}